    ir_arena: &mut Arena<IR>,
    expr_arena: &mut Arena<AExpr>,
    scratch: &mut Vec<Node>,
    hooks: ExecutionHooks,
) -> PolarsResult<Node> {
    #[allow(dead_code)]
    let verbose = verbose();


    let opt = StackOptimizer {};
    let mut rules: Vec<Box<dyn OptimizationRule>> = Vec::with_capacity(8);

    #[allow(unused_assignments)]
